#ifndef INSTRUCTION_HPP
#define INSTRUCTION_HPP

#include <utility>
#include "Common.h"
#include <string>
#include <iostream>

enum Type {
    R, I, S, B, U, J
};

class InstructionBase {
public:
    unsigned int opcode;
    unsigned int rs1;
    unsigned int rs2;
    unsigned int rd;
    unsigned int funct3;
    unsigned int funct7;
    Immediate imm;
    Instruction inst;
    Type t;

    InstructionBase() : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(-1), t(Type::I) {}
    InstructionBase(unsigned int instruction) : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(instruction), t(Type::I) {}

    static InstructionBase nop() {
        return InstructionBase();
    }

    bool is_nop() const {
        return inst == -1;
    }

    static unsigned int bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static unsigned int get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & ((1U << (hi - lo + 1)) - 1);
    }

    static unsigned int expand_digit(unsigned int digit, int lo) {
        if (digit != 0) {
            return 1U << lo;
        } else {
            return 0;
        }
    }

    bool is_valid(const std::string &key) const {
        if (t == Type::R && key == "imm") return false;
        if (t == Type::I && (key == "rs2" || key == "funct7")) return false;
        if (t == Type::S && (key == "rd" || key == "funct7")) return false;
        if (t == Type::B && (key == "rd" || key == "funct7")) return false;
        if (t == Type::U && (key == "rs1" || key == "rs2" || key == "funct3" || key == "funct7")) return false;
        if (t == Type::J && (key == "rs1" || key == "rs2" || key == "funct3" || key == "funct7")) return false;
        return true;
    }

    void verify(const std::string &key) const {
        if (!is_valid(key)) {
            throw InvalidAccess();
        }
    }

    virtual void debug() const {
        if (is_nop()) {
            std::cout << "NOP";
            return;
        }

        if (opcode == 0b0010011) {
            if (t == Type::I && funct3 == 0b000) std::cout << "LUI";
            else if (t == Type::I && funct3 == 0b010) std::cout << "AUIPC";
            else if (opcode == 0b1100111 && funct3 == 0b000) std::cout << "JAL";
            else if (opcode == 0b1100111 && funct3 == 0b010) std::cout << "JALR";
            else if (t == Type::B) std::cout << "branch";
            else if (t == Type::S) std::cout << "store";
            else if (t == Type::I) std::cout << "load";
            else if (opcode == 0b0110011) std::cout << "R-type instruction";
            else std::cout << "unknown";
        } else {
            std::cout << "unknown";
        }
    }

    bool has_op1() const {
        return t != Type::U && t != Type::J;
    }

    bool has_op2() const {
        return t == Type::R || t == Type::S || t == Type::B;
    }
};

class InstructionR : public InstructionBase {
public:
    InstructionR(unsigned int instruction) : InstructionBase(instruction) {
        opcode = get_digits(instruction, 6, 0);
        rd = get_digits(instruction, 11, 7);
        funct3 = get_digits(instruction, 14, 12);
        rs1 = get_digits(instruction, 19, 15);
        rs2 = get_digits(instruction, 24, 20);
        funct7 = get_digits(instruction, 31, 25);
    }
};

class InstructionI : public InstructionBase {
public:
    InstructionI(unsigned int instruction) : InstructionBase(instruction) {
        opcode = get_digits(instruction, 6, 0);
        rd = get_digits(instruction, 11, 7);
        funct3 = get_digits(instruction, 14, 12);
        rs1 = get_digits(instruction, 19, 15);
        imm = (Immediate)((instruction >> 20) & 0xFFF); // Extract immediate and sign-extend
    }
};

class InstructionS : public InstructionBase {
public:
    InstructionS(unsigned int instruction) : InstructionBase(instruction) {
        opcode = get_digits(instruction, 6, 0);
        funct3 = get_digits(instruction, 14, 12);
        rs1 = get_digits(instruction, 19, 15);
        rs2 = get_digits(instruction, 24, 20);
        imm = (Immediate)(((instruction >> 7) & 0x1F) | ((instruction >> 25) << 5));
    }
};

class InstructionB : public InstructionBase {
public:
    InstructionB(unsigned int instruction) : InstructionBase(instruction) {
        opcode = get_digits(instruction, 6, 0);
        funct3 = get_digits(instruction, 14, 12);
        rs1 = get_digits(instruction, 19, 15);
        rs2 = get_digits(instruction, 24, 20);
        imm = (Immediate)(((instruction >> 8) & 0xF) << 1 | ((instruction >> 25) & 0x7F) << 5 | ((instruction >> 7) & 0x1) << 11);
    }
};

class InstructionU : public InstructionBase {
public:
    InstructionU(unsigned int instruction) : InstructionBase(instruction) {
        opcode = get_digits(instruction, 6, 0);
        rd = get_digits(instruction, 11, 7);
        imm = (Immediate)((instruction >> 12) << 12 | (instruction >> 20) << 20 | ((instruction >> 31) & 0x1) << 31);
    }
};

class InstructionJ : public InstructionBase {
public:
    InstructionJ(unsigned int instruction) : InstructionBase(instruction) {
        opcode = get_digits(instruction, 6, 0);
        rd = get_digits(instruction, 11, 7);
        imm = (Immediate)(((instruction >> 21) & 0x3FF) << 1 | ((instruction >> 20) & 0x1) << 11 | ((instruction >> 12) & 0xFF) << 12 | ((instruction >> 31) & 0x1) << 20);
    }
};

#endif // INSTRUCTION_HPP
